/bin/bash -lc "python - <<'PY'
import json
x=json.load(open('canonical-input.json'))
for k,v in x.items():
 print(k, type(v).__name__, len(v) if isinstance(v,(list,dict,str)) else v)
 if isinstance(v,list) and k not in ['contextGoals','goals','sourceGoals']:
  for i,g in enumerate(v):
   if isinstance(g,dict): print(i,{k:g[k] for k in ['id','goalId','shortKey','label','name'] if k in g}, list(g.keys()))
PY"

